pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // 1. Admissible domain: any uint16
        vm.assume(_feeRate > 5000);

        // 2. Try initialize and capture revert boolean
        bool reverted;
        try c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // 3. General rule: if _feeRate > 5000, call must revert AND feeRate must remain 0 (not stored).
        assertTrue(reverted && c.feeRate() == 0);
    }
}

