pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 feeRate) public {
        // Restrict to the domain where the difference is observable: feeRate > 5000
        vm.assume(feeRate > 5000);

        // Attempt initialization with an excessive fee rate
        try c.initialize(
            address(0), // _baseToken
            address(0), // _nft
            0,          // _virtualBaseTokenReserves
            0,          // _virtualNftReserves
            0,          // _changeFee
            feeRate,    // _feeRate
            bytes32(0), // _merkleRoot
            false,      // _useStolenNftOracle
            false       // _payRoyalties
        ) {
            // Should never succeed
            assertTrue(false, "initialize should revert");
        } catch {
            // After revert, feeRate must be 0 in the reference, but buggy stores the value
            assertTrue(c.feeRate() == 0);
        }
    }
}

