pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate, address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Restrict to the domain where the bug is triggered: feeRate > 5000
        vm.assume(_feeRate > 5000);
        // Ensure baseToken and nft are not zero addresses (to avoid unnecessary complications)
        vm.assume(_baseToken != address(0));
        vm.assume(_nft != address(0));
        // The call should revert, so we capture that
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            // Should not succeed; if it does, the test fails because we expect a revert
            assertTrue(false);
        } catch {
            // After revert, the stored feeRate must be 0 (reference behavior)
            assertTrue(c.feeRate() == 0);
        }
    }
}

